"""Publish the thin wrapped torso correction and matched diagnostic evidence."""
import hashlib,json,re,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-wrap-r6'
row=json.loads((OUT/'refinement-metrics.json').read_text());ID=row['id']
checks=json.loads((OUT/'verification.json').read_text());contacts=json.loads((OUT/'attachment-verification.json').read_text())
band=json.loads((OUT/'band-verification.json').read_text());collar=json.loads((OUT/'collar-verification.json').read_text());isolated=json.loads((OUT/'isolated-review.json').read_text())
assert checks['source_sha256']==hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest()
assert row['triangles']==checks['triangles']==1800
assert contacts['result']=='PASS' and contacts['endpoints']==50 and contacts['sampled_poses']==35
assert band['result']=='PASS' and band['connected_components']==1 and band['band_rib_seatings']==12
assert collar['result']=='PASS' and collar['upper_torso_seatings']==2
assert isolated['rift-titan-wrap-r6']['source_sha256']==checks['source_sha256']
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — thin wrapped torso r6</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}}}</style>
<h1>Rift Titan — thin wrapped torso r6</h1>
<p><strong>Side orientation corrected:</strong> the creature's front faces left, matching the concept. Both r5/r6 whole-model and isolated side comparisons use that direction. These are new camera renders of the saved models.</p>
<div class="pair"><figure><img src="concept-side.png" alt="Concept side with head facing left"><figcaption>Concept — front/head left, back right</figcaption></figure><figure><img src="{ID}--side.png" alt="Saved model side with front facing left"><figcaption>Saved model — front/head left, back right</figcaption></figure></div>
<p>The previous thick front plate has been replaced by a narrow sculpted stone band that closes around the entire torso. Twelve continuous bowed metal ribs pass behind it into the lower bowl. The central V is small and follows the band. The upper collar is also a closed stone ring: its left and right sections seat into the larger upper torso stones, and the torso and neck ribs attach to that ring.</p>
<p><strong>{row['triangles']:,} triangles · {row['ratio']:.3f}× native Stone Golem · soft cap 1,800</strong>. One mesh/material, four 512px maps, eight retained bones and seven actions. Fifty support contacts pass 35 sampled poses; the middle band and upper collar are each one closed connected ring. This is a torso candidate for visual review. Fracture, corrosion and weathering detail remain unfinished.</p>
<h2>Torso reference and saved model</h2><div class="pair"><figure><img src="concept-torso.png" alt="User-supplied torso crop"><figcaption>Concept — thin band wraps around the cage, with ribs above and below</figcaption></figure><figure><img src="{ID}--detail.png" alt="Saved r6 torso close-up"><figcaption>r6 — continuous ribs, narrow wrap and smaller V</figcaption></figure></div>
<div class="pair"><figure><img src="concept-v-band-detail.png" alt="User-supplied close-up of the V and sculpted stone band"><figcaption>Concept band close-up</figcaption></figure><figure><img src="rift-titan-wrap-r6--isolated-side.png" alt="Isolated saved torso in side view"><figcaption>Saved torso side diagnostic — surrounding parts hidden so the wrap is visible</figcaption></figure></div>
<h2>Isolated torso — matched before and after</h2><p>These diagnostics extract the torso ribs, band, collar and lower keel from each saved model. Arms, shoulders, head, neck and the crystal cluster are hidden for visibility. The source models are unchanged.</p><div><button data-isolated="front">Front</button><button data-isolated="side">Side</button><button data-isolated="rear">Rear</button></div><div class="pair"><figure><img id="isolated-before" src="rift-titan-torso-r5--isolated-front.png" alt="Isolated r5 torso"><figcaption>r5 — thick front V plate and split rib layout</figcaption></figure><figure><img id="isolated-after" src="rift-titan-wrap-r6--isolated-front.png" alt="Isolated r6 torso"><figcaption>r6 — narrow closed band and ribs continuous through the torso</figcaption></figure></div>
<h2>Whole model — matched views</h2><div><button data-view="three-quarter">Surface</button><button data-view="clay">Clay</button><button data-view="front">Front</button><button data-view="side">Side</button><button data-view="detail">Torso</button></div><div class="pair"><figure><img id="before" src="../rift-titan-torso-r5/underworld-boss-rift-titan-torso-r5--three-quarter.png" alt="Previous r5 model"><figcaption>Previous r5</figcaption></figure><figure><img id="after" src="{ID}--three-quarter.png" alt="Saved r6 model"><figcaption>Current r6 — torso correction; other areas retained</figcaption></figure></div>
<h2>Concept front and side</h2><div class="pair"><img src="concept-front.png" alt="User-supplied concept front view"><img src="concept-side.png" alt="User-supplied concept side view"></div>
<h2>Full adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Rift Titan concept sheet">
<h2>Native donor reference</h2><img style="max-width:900px" src="../../2026-10-04/detail-r2/donor-StoneGolem--three-quarter.png" alt="Native Stone Golem quality and cost reference">
<p>The r5 head, shoulders, limbs, rig and actions remain. Neck roots are reseated into the upper ring. Native loader admission and live performance are separate pending checks. Rift Titan remains under visual review; the adequate boss tally remains 1/6.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--attack.png">Attack pose</a> · <a href="verification.json">Geometry/export checks</a> · <a href="attachment-verification.json">Saved support checks</a> · <a href="band-verification.json">Closed band checks</a> · <a href="collar-verification.json">Collar ring checks</a> · <a href="isolated-review.json">Diagnostic provenance</a> · <a href="torso-authoring.json">Construction</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='../rift-titan-torso-r5/underworld-boss-rift-titan-torso-r5--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});document.querySelectorAll('button[data-isolated]').forEach(b=>b.onclick=()=>{{document.getElementById('isolated-before').src='rift-titan-torso-r5--isolated-'+b.dataset.isolated+'.png';document.getElementById('isolated-after').src='rift-titan-wrap-r6--isolated-'+b.dataset.isolated+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_wrapped_torso.py','tools/refine-rift-titan-wrap-r6.py','tools/review-rift-titan-wrap-r6.py','tools/review-rift-titan-wrap-isolated-r6.py','tools/verify-rift-titan-wrap-r6.py','tools/publish-rift-titan-wrap-r6.py',row['source'],'docs/art/creature-concepts/2026-10-03/the-rift-titan.png']+[p.relative_to(ROOT).as_posix() for p in sorted(OUT.glob('concept-*.png'))]
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},acceptance='unaccepted thin wrapped torso candidate; tally remains 1/6'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
for revision in ('rift-titan-torso-r5','rift-titan-wrap-r6'):
 for view in ('front','side','rear'):assert (OUT/(revision+'--isolated-'+view+'.png')).is_file()
print('VERIFIED r6 review links, supported closed wrap, cap and source hashes')
